118	    pub(super) fn promote_function_aliases(&mut self) {
119	        let aliases = std::mem::take(&mut self.pending_function_aliases);
120	        for _ in 0..aliases.len() {
121	            let mut changed = false;
122	            for (name, target) in &aliases {
123	                let key = self.scoped_key(name);
124	                if self.data.function_results.contains_key(&key) {
125	                    continue;
126	                }
127	                if let Some(result) = self.data.function_results.get(&self.scoped_key(target)).cloned() {
128	                    self.data.function_results.insert(key, result);
129	                    changed = true;
130	                }
131	            }
132	            if !changed {
133	                break;
134	            }
135	        }
136	    }
